"""Статья «Пруды и биопруды» для раздела «Справочники → Пруды».

Исходный текст подготовлен ООО «Тэга плюс», здесь он проверен, исправлен и дополнен. Рекламный блок убран.
Что исправлено:
 - «пруд-копань до 20 соток» неверно: по публикациям о Водном кодексе (Закон № 148-З, с 01.01.2027) один пруд-копань на участок, зеркало до 0,01 га (1 сотка),
   глубина до 2 м, не более 5 % площади участка, без проектной документации, для личных нужд; «20 соток» относится к уже существующим непроточным водоёмам;
 - отступ 3 м от границы соседнего участка относится к Закону № 148-З, а не к СН 3.01.03-2020; пределы закона помечены «сверьте с текстом»;
 - убраны: таблица брендов и «мировой топ», «9500+ построенных прудов», ссылка на журнал, цены и доли бюджета, «30–50 лет» для мембраны (срок зависит от материала и монтажа);
 - убраны растения без зимостойкости для Беларуси (понтедерия, турча) и совет брать растения из природных водоёмов;
 - глубина промерзания «около 1 м, по проекту» вместо «0,8–1,2 м»; кой-пруд глубиной от 1,8 м не укладывается в 2 м для копани, это уже другой режим;
 - эмпирические цифры (оборот, объём фильтра, УФ, аэрация, плотность посадки) оставлены и помечены как ориентиры практики;
 - расчёт плёнки дополнен оговоркой: наклонные стенки и террасы требуют запаса больше 10 %.
Источники: Закон Республики Беларусь № 148-З (Водный кодекс, ред. 2026); СН 3.01.03-2020; техническая литература по прудам и constructed wetlands; паспорта производителей.
"""
from art_heat import _sec, _ul, _tbl, _note, _box, _p, _errs, _kpis
from art_pond_figs import f_nitrogen, f_profile, f_turn

LAW = "https://pravo.by/document/?guid=12551&p0=H12600148"


def article():
    s = ""
    s += _kpis([("4–6 нед", "созревание биофильтра: «зелёная вода» в начале нормальна"), ("0,5–4 об/ч", "оборот воды: от декора до кой-пруда, ориентир практики"),
                ("≥ 1,5 м", "зимовальная яма ниже промерзания, если в пруде зимует рыба"), ("30–50 %", "зеркала занимают растения в декоративном пруду")])
    s += f_nitrogen()
    s += _box("Главный принцип",
              "Баланс важнее бренда: рыба, корм, растения, бактерии и оборудование должны сходиться в одном уравнении азота. Перекормленные кои при слабом биофильтре погубят пруд дороже любой мембраны, "
              "а недобор растений превратит купальный пруд в болото за пару сезонов.")

    s += _sec("0", "Суть: пруд это экосистема, а не ёмкость с водой",
              _p("Пруд держится на азотном цикле: корм, листва и отходы рыбы дают аммоний, бактерии переводят его в нитрит и затем в нитрат, а нитрат забирают растения. "
                 "Оборудование (насос, скиммер, биофильтр, УФ, аэрация) ускоряет и страхует этот цикл, но не заменяет его. Пока бактерии не заселили фильтр, аммоний и нитрит опасны для рыбы, "
                 "поэтому первые недели вода мутная или зелёная, рыбу не торопятся пускать, а корм дают минимально.")
              + _ul(["<b>Назначение первично.</b> Декоративный пруд, кой-пруд и пруд для купания это три разные задачи с разной глубиной, потоком и фильтром.",
                     "<b>Профиль закладывают котлованом.</b> Террасы для растений и зимовальную яму потом не «докупить».",
                     "<b>Зима закладывается заранее.</b> Глубина ямы, аэрация и сервис решаются на стадии проекта."]))

    s += _sec("1", "Типы прудов",
              _tbl(["Тип", "Глубина и зоны", "Оборудование (ориентир практики)", "Особенности"], [
                  ["Декоративный биопруд", "1,2–2,0 м с террасами; зимовальная яма от 1,5–1,8 м, если зимует рыба", "Оборот 0,5–1 об/ч, скиммер, биофильтр около 10–15 % объёма, аэрация", "Основа частного сада; растения главный фильтр"],
                  ["Кой-пруд", "От 1,8 м, без мелководных зарослей в чаше", "Оборот 2–4 об/ч, донный сток, барабанный фильтр и биофильтр около 30–40 %, УФ, сильная аэрация", "Рыба доминирует: оборудования заметно больше, чем у декоративного"],
                  ["Пруд для купания (биопул)", "Плавательная зона 1,4–2 м и зона регенерации 30–50 % площади", "Оборот 1–2 об/ч, скиммеры, болотный (bog) фильтр, движение воды в регенерации", "Без хлора: чистоту дают растения и медленная фильтрация"],
                  ["Болотный фильтр как модуль", "Слой щебня 0,2–0,4 м с перфорированной раздачей", "Отдельный насос или самотёк после биофильтра", "Доводка нитратов и фосфатов; ставится и к готовому пруду"],
                  ["Бентонит или глиняный замок", "Профиль любой", "Без плёнки: бентонитовый мат или уплотнённая глина", "Большие водоёмы; риск пересыхания и прорастания корней"],
              ])
              + _p("<b>Материал чаши.</b> Каучуковая EPDM и бутил наиболее эластичны и ремонтопригодны; ПВХ дешевле, но на УФ в местах складок стареет быстрее; бетонная чаша требует эластичной гидроизоляции "
                   "и трескается по осадке. Срок службы зависит от материала, толщины (для EPDM обычно 1,0–1,5 мм) и качества монтажа, обещанный срок смотрите в гарантии производителя.")
              + _note("Тенденции последних лет: купальные пруды вместо хлорных бассейнов (зона регенерации и bog-фильтр стали отраслевой схемой), насосы с переменной частотой вращения (меньше электричества в межсезонье), "
                      "датчики кислорода и pH с автоматикой, пруд как запас воды для полива. В Беларуси это пока единичные проекты, но схема воспроизводима."))

    s += _box("Что говорит закон о прудах на участке",
              "Водный кодекс (<a href=\"" + LAW + "\">Закон № 148-З</a>, нормы применяются с 01.01.2027) разрешает садовый пруд-копань без проектной документации. По публикациям о кодексе: один пруд на участок, "
              "зеркало не более 0,01 га (1 сотка), глубина не более 2 м, не более 5 % площади участка, для личных нужд, не ближе 3 м от границы соседнего участка (от береговой линии); "
              "уже существующие законные пруды засыпать не требуют. «20 соток» из ранних публикаций относится к существующим непроточным водоёмам, а не к новому пруду. "
              "Всё, что крупнее или глубже, идёт по общему порядку: согласования и проект. Сверьте цифры с текстом закона и с местным райисполкомом до начала земляных работ. "
              "Для кой-пруда глубиной 1,8–2,5 м и для купального пруда площадью более сотки действуют не эти упрощения, а общий порядок.")

    s += _sec("2", "Геометрия: террасы, глубины, количество плёнки",
              f_profile()
              + _tbl(["Параметр", "Ориентир практики", "Зачем"], [
                  ["Зимовальная яма", "От 1,5–1,8 м и глубже промерзания (около 1 м, по проекту)", "Рыба и мембрана переживают лёд; летом прохладное убежище"],
                  ["Болотная терраса 0–10 см", "10–20 % площади зеркала", "Ирис, калужница, осоки: быстрый старт биоплёнки"],
                  ["Мелководье 10–40 см", "15–25 % площади", "Камыш, сусак, мята водная; нерест и прогрев"],
                  ["Глубоководная зона 40–80 см", "Остальная часть до ямы", "Кувшинки (1 шт на 1–2 м²), стабильная температура"],
                  ["Откосы", "Террасы до 30–35°, яма круче, до 60°", "Плёнка и камень не ползут; безопасный выход"],
                  ["Бортик", "Плёнка выше уровня земли на 10–15 см и обсыпана", "Дождевая вода с удобрениями не стекает в пруд"],
              ], True)
              + _p("<b>Пример расчёта плёнки и геотекстиля</b> для пруда 6×4 м глубиной 1,8 м со свесами по 0,5 м. Длина полотна 6 + 2×1,8 + 2×0,5 = 10,6 м, ширина 4 + 2×1,8 + 2×0,5 = 8,6 м, "
                   "площадь около 91 м², с нахлёстами и подрезкой около 100 м². Геотекстиль 300 г/м² идёт на то же ложе, и ещё по камню в местах нагрузки. Объём воды при среднем заглублении 1,1 м около 26 м³: от него считают насос и фильтр. "
                   "Это минимальный расчёт для простого ложа с прямыми стенками. Террасы и пологие откосы увеличивают площадь, поэтому запас берут по раскрою, а не по формуле.")
              + _box("Запоминалка", "Террасы держат пруд, яма держит зиму. Без террас растениям негде жить, а плёнке не на чем лежать; без ямы ниже промерзания рыба не переживёт ледостав."))

    s += _sec("3", "Оборудование: насос, биофильтр, УФ, аэрация",
              f_turn()
              + _ul(["<b>Насос.</b> Расход Q = V × оборот. Для 26 м³ декоративного пруда Q = 13–26 м³/ч; напор складывается из подъёма воды до фильтра (около 1,0–1,5 м) и потерь трассы, итог часто 2,5–3 м. "
                     "Хорошо работает насос с регулируемой скоростью: на лето 100 %, весной и осенью 40–60 %. Для кой-пруда считают от 2 об/ч и добавляют донный сток, чтобы грязь уходила в фильтр.",
                     "<b>Биофильтр.</b> Объём загрузки 10–15 % объёма пруда для декоративного, 30–40 % для кой. Поток через фильтр равен расходу насоса. Фильтр ставят выше уровня воды, возврат самотёком: "
                     "при отключении питания пруд не должен сифонить.",
                     "<b>УФ-стерилизатор.</b> Практика 1–3 Вт на 1 м³ против «зелёной воды». Это косметика: аммоний и нитрит УФ не убирает.",
                     "<b>Аэрация.</b> Мембранный компрессор около 60–100 л/мин на 10 м³ держит кислород и полынью зимой, летом страхует биофильтр в жару.",
                     "<b>Структура затрат.</b> У кой-пруда заметную долю занимает оборудование, у купального пруда земляные работы и зона регенерации с растениями; первый сезон закладывает сервис. "
                     "Цены на оборудование и работы здесь не приводятся: они меняются, запрашивайте расчёт по вашей чаше."]))

    s += _sec("4", "Растения-биофильтры: зоны, виды, плотность",
              _tbl(["Зона", "Зимостойкие виды для Беларуси", "Плотность (ориентир)", "Роль"], [
                  ["Болотная, 0–10 см", "Ирис аировидный, калужница, осока, ситник", "5–7 шт/м²", "Старт биоплёнки, вынос азота и фосфора"],
                  ["Мелководье, 10–40 см", "Камыш озёрный, сусак, мята водная, рогоз узколистный (в контейнере)", "3–5 шт/м²", "Корневая доочистка, приют для зоопланктона"],
                  ["Глубоководная, 40–80 см", "Кувшинка белая и четырёхгранная, кубышка", "1 шт на 1–2 м²", "Тень против нагрева и водорослей"],
                  ["Плавающие", "Водокрас, рдесты (дозированно)", "1–2 шт/м²", "Потребляют нитрат из толщи воды"],
                  ["Зона регенерации биопула", "Ирис, камыш, рогоз узколистный, сусак на щебне bog-фильтра", "7–9 шт/м²", "Замыкают цикл: нитрат и фосфат купальной зоны"],
              ])
              + _ul(["<b>Агрессоры в контейнеры.</b> Рогоз широколистный, ежеголовник и тростник за несколько сезонов вытесняют остальное и рвут плёнку корнями; допускаются только в корзинах.",
                     "<b>Правило площади.</b> Растения занимают порядка 30–50 % зеркала декоративного пруда (в купальном 30–50 % общей площади составляет зона регенерации), иначе нитрат копится и вода цветёт каждое лето.",
                     "<b>Откуда растения.</b> Из питомников, а не из природных водоёмов: так не занесёте болезни и инвазивные виды и не нарушите закон об охране растений.",
                     "<b>Старт сезона.</b> Посадки весной при прогреве воды выше примерно 10 °C; первые 4–6 недель минимум корма и рыбы."])
              + _p("<b>Пример посадки</b> для пруда 26 м³ с зеркалом 24 м²: болотная терраса 4 м² (около 24–28 растений), мелководье 5 м² (18–22), 4–6 кувшинок, 3–4 плавающих. Всего порядка 50–60 растений. "
                   "Это дешёвый и долговечный фильтр, но его нужно прореживать и ухаживать раз в сезон."))

    s += _sec("5", "Монтаж и зимовка: десять правил",
              _ul(["<b>Котлован.</b> От центра к краям: террасы выводят по уровню, яму делают последней; грунт из ямы не подсыпают под террасы, осадка порвёт плёнку.",
                   "<b>Геотекстиль</b> 300 г/м² под плёнкой по всему ложу и сверху в местах камня и ступеней. Корни и камни главные враги чаши.",
                   "<b>Плёнка со складками.</b> Укладывают в тёплую погоду, не «в струну», расправляют под наливом воды: натянутая плёнка рвётся на углах при осадке.",
                   "<b>Анкерная траншея и бортик.</b> Край плёнки заводят в траншею за береговую линию и поднимают бортик над землёй, чтобы дождь не нёс удобрения с газона.",
                   "<b>Скиммер и донный сток</b> монтируют до засыпки, с фланцами и герметиком; трассы идут с уклоном, без петель «против течения».",
                   "<b>Биофильтр выше уровня воды,</b> возврат самотёком или с обратным клапаном, чтобы авария не сифонила пруд.",
                   "<b>Электрика у воды.</b> УЗО 30 мА (дифференциальный автомат) на всё водное оборудование, кабель в трубе вне чаши, оборудование под навесом с вентиляцией; схема и сечения по ПУЭ и проекту. ИБП на компрессор зимней аэрации.",
                   "<b>Пуск.</b> Заполнение, проверка уровней, внесение бактерий, посадка растений, рыба через 4–6 недель; первый месяц аммоний и нитрит измеряют тестами, а не «на глаз».",
                   "<b>Зима.</b> Пруд не сливают (пустую чашу выдавит грунт); насос убирают или опускают ниже примерно 80 см, аэратор держит полынью над ямой; лёд не долбят, ударная волна вредит рыбе и мембране.",
                   "<b>Сервисный доступ.</b> Люк или площадка у фильтра и насоса, розетка и свет в техзоне, иначе обслуживание превращается в раскопки и пруд забрасывают."])
              + _box("Безопасность и вода",
                     "Если на участке бывают дети, продумайте ограждение или мелководный выход, знаки и спасательные средства: ответственность за безопасность лежит на владельце. "
                     "Купание в пруду регулируют отдельные санитарные требования к воде, они не равны требованиям к декоративному водоёму. Стоячая вода привлекает комаров: движение воды, рыба и растения решают это без химии.")
              + _note("Водяные потребители и зимнее содержание зависят от вашей чаши, климата зимы и рыбы: перед запуском составьте письменный регламент сезонов."))

    s += _sec("6", "Типичные ошибки: 12 способов получить болото вместо пруда",
              _errs([
                  ("Плоская яма без террас", "Растениям негде жить, плёнка ползёт, пруд стареет за сезон.", "Террасы по уровню на этапе котлована."),
                  ("Глубина 1 м «для экономии»", "Промерзает до дна зимой, перегревается летом, цветут водоросли.", "Зимовальная яма ниже промерзания, если зимует рыба."),
                  ("ПВХ по щебню без геотекстиля", "Прокол в первый сезон, ремонт с осушением.", "Геотекстиль под плёнкой и под камнем."),
                  ("Плёнка «в струну»", "Трещины по складкам при осадке грунта и наливе.", "Свободная укладка, расправка под водой."),
                  ("Нет бортика и анкерной траншеи", "Ливень с газона несёт удобрения: цветение каждое лето.", "Бортик, траншея, отсыпка камнем."),
                  ("Насос «помощнее»", "Размыв террас, вымывание биоплёнки, счёт за электричество.", "Расход по обороту типа пруда, регулируемый насос."),
                  ("УФ вместо биофильтра", "Вода прозрачная, но аммоний и нитрит остаются, рыба болеет.", "Биофильтр по объёму и типу, УФ как добавка."),
                  ("Перенаселение и перекорм", "Азота больше мощности фильтра: замор и водоросли.", "Ориентир 1 см рыбы на 50 л, корм за 5 минут."),
                  ("Растений «пара кустов»", "Нитрат некому забирать, зелёная вода к июлю.", "Растения по зонам, 30–50 % зеркала."),
                  ("Фильтр ниже уровня без защиты", "Отключили свет, сифон осушил пруд за часы.", "Фильтр выше воды, самотёк или обратный клапан."),
                  ("Слив на зиму или долблёный лёд", "Чашу выдавливает грунт, рыба гибнет от ударной волны.", "Не сливать, аэратор, никакой долбёжки."),
                  ("Техзона без доступа", "Обслуживание это раскопки, пруд бросают на третий сезон.", "Площадка, свет, розетка и люк у фильтра в проекте."),
              ]))

    s += _sec("7", "Приоритеты и чек-лист заказчика",
              _p("Вопросы подрядчику до договора.")
              + _ul(["Есть ли профиль чаши в разрезе, с террасами, зимовальной ямой, отметками и уровнем воды?",
                     "Как посчитан оборот: насос, напор, объём биофильтра, ваши цифры для вашего пруда?",
                     "Какие растения и сколько по зонам, что делаете с агрессорами?",
                     "Как прописана зима: аэрация, насос, полынья, лёд, регламент?",
                     "Электрика у воды: УЗО, трассы, ИБП компрессора в смете?",
                     "Гарантия на чашу и оборудование, входит ли сервис первого сезона?",
                     "Подходит ли пруд под упрощённый порядок закона по размерам, или нужны согласования?"])
              + _box("Красные флаги", "«Пруд без растений, чистая вода из фильтра»; плёнка без геотекстиля «и так будет»; глубина «метр с лихвой» при зимующей рыбе; насос вдвое мощнее расчёта «про запас»; "
                                      "нет зимнего сценария и сервиса; пруд крупнее допустимого без согласований или ближе 3 м к границе. Любого пункта достаточно, чтобы остановиться.")
              + _p("Пять тезисов, с которыми можно принимать решение.")
              + _ul(["Пруд это экосистема: азотный цикл держат бактерии и растения, оборудование лишь страхует.",
                     "Профиль решает всё: террасы и зимовальная яма закладываются котлованом.",
                     "Оборудование считают по обороту: 0,5–1 об/ч декор, 1–2 купальный, 2–4 кой; УФ косметика, биофильтр обязателен.",
                     "Растения это постоянный фильтр: 30–50 % зеркала по зонам, агрессоры только в контейнерах.",
                     "До земляных работ проверьте размеры по закону, электрику у воды и зимний регламент."])
              + _note("Источники: Закон Республики Беларусь № 148-З (Водный кодекс) по публикациям, текст сверьте на pravo.by; СН 3.01.03-2020; паспорта оборудования. "
                      "Цифры оборота, фильтра, УФ и плотности посадки это ориентиры практики, а не нормативы. Оценки не оферта."))
    return s
